/** Экран входа (признак «разлогинило» — тикет требует работу БЕЗ повторного входа). */
const LOGIN_MARKERS = ['מספר נייד', 'בואו נתחיל'];

/** Холодный старт: terminate → activate → «בית». Окно сбоя iOS закрывается и считается падением (ошибка).
 *  Экран входа вместо «בית» — ошибка «перелогин» (#1b6593 מה רצוי: без выхода и повторного входа). */
export async function coldStart(where: string, timeout = 60000) {
  const id = appId();
  await driver.terminateApp(id).catch(() => {});
  await driver.activateApp(id);
  let crashed = false; let login = false;
  await driver.waitUntil(async () => {
    if (await dismissCrashAlert()) { crashed = true; return true; }
    for (const m of LOGIN_MARKERS) if (await shown(byTextContains(m))) { login = true; return true; }
    return shown(byText('בית'));
  }, { timeout, interval: 1000, timeoutMsg: `${where}: после холодного старта «בית» не появилась за ${timeout / 1000} с` });
  if (crashed) throw new Error(`${where}: окно сбоя iOS при холодном старте`);
  if (login) throw new Error(`${where}: после холодного старта — экран входа (нужен перелогин, #1b6593)`);
}

