/** Placeholder пустого поля поиска (атрибут TextField или отдельный текст). */
export async function searchPlaceholder(): Promise<string> {
  const f = (await searchField()) as unknown as El;
  await f.waitForDisplayed({ timeout: 20000 });
  if (driver.isAndroid) return String((await f.getAttribute('hint').catch(() => null)) ?? (await f.getText()));
  const ph = String((await f.getAttribute('placeholderValue').catch(() => null)) ?? '');
  if (ph) return ph;
  return String((await f.getAttribute('value').catch(() => '')) ?? '');
}
/** Дождаться, что placeholder стал ожидаемым (после переключения сегмента). */
export async function expectPlaceholder(expected: string, where: string) {
  let last = '';
  await driver.waitUntil(async () => {
    last = await searchPlaceholder();
    if (last.includes(expected)) return true;
    return shown(byText(expected));                         // placeholder отдельным текстом
  }, { timeout: 10000, timeoutMsg: `${where}: placeholder не «${expected}» (сейчас «${last}»)` });
}

